              if (currencies.isEmpty)
                const SliverToBoxAdapter(child: Center(child: Text('No data')))
              else
                _buildCurrencySliver(currencies),
              if (currencies.isNotEmpty && news.isNotEmpty)
                _buildSectionHeader(context, context.loc.dashboardNews),
              if (news.isEmpty && currencies.isNotEmpty)
                const SliverToBoxAdapter(child: Center(child: Text('No data')))
              else
                _buildNewsSliver(news),
            ],
          );
        },
      ),
    );
